import struct, random

# Data type: raw complex double array
# Encoding: sequence of elements, each element is two 64-bit IEEE-754 doubles
# layout in memory: [re0, im0, re1, im1, ...]
# Our goal: produce bytes that are valid arrays for various BLAS complex-double
# routines used by the fuzzers: vectors and matrices (general/triangular/
# Hermitian/band/packed), possibly with negative/positive strides. The fuzzer
# chooses sizes and resizes buffers; we just need to provide interesting initial
# content that decodes to sensible values across many cases.
# Strategy:
# - Generate a mixture of patterns that exercise corner cases: zeros, NaNs/Inf,
#   small integers, alternating signs, unit/identity-like diagonals (for matrices),
#   sinusoidal sequences, random normals, and special values on diagonals for
#   Hermitian/triangular paths.
# - Keep total output <= 4096 bytes.
# - Because the stubs call FUZZ_PARAM_STR multiple times, a single returned
#   buffer will be sliced/consumed independently; to be broadly useful, we fill
#   it with concatenated regions of different patterns, so any slice the fuzzer
#   takes likely lands on something meaningful.

MAX_BYTES = 4096


def _pack_complex(values):
    # values: iterable of (re, im) float pairs
    out = bytearray()
    for re, im in values:
        out += struct.pack('<dd', re, im)
    return out


def _pattern_zeros(n):
    return _pack_complex(((0.0, 0.0) for _ in range(n)))


def _pattern_ones(n):
    return _pack_complex(((1.0, 0.0) for _ in range(n)))


def _pattern_i(n):
    return _pack_complex(((0.0, 1.0) for _ in range(n)))


def _pattern_alternating(n):
    vals = []
    for i in range(n):
        s = -1.0 if (i % 2) else 1.0
        vals.append((s * (i % 5), -s * ((i + 1) % 5)))
    return _pack_complex(vals)


def _pattern_small_integers(n):
    vals = []
    for i in range(n):
        vals.append((float(i % 11 - 5), float((i * 3) % 7 - 3)))
    return _pack_complex(vals)


def _pattern_sin_cos(n):
    vals = []
    # deterministic frequencies to create nontrivial correlations
    for i in range(n):
        x = i / max(1, n)
        vals.append((
            0.75 * __import__('math').sin(2.0 * __import__('math').pi * (3.0 * x)),
            0.5 * __import__('math').cos(2.0 * __import__('math').pi * (5.0 * x)),
        ))
    return _pack_complex(vals)


def _pattern_random_normal(n, rng):
    vals = []
    for _ in range(n):
        vals.append((rng.gauss(0.0, 1.0), rng.gauss(0.0, 1.0)))
    return _pack_complex(vals)


def _pattern_specials(n):
    # mixture of finite edge magnitudes and some Infs/NaNs but mostly finite to
    # remain useful. Put specials sparsely.
    vals = []
    import math
    for i in range(n):
        if i % 19 == 0 and i != 0:
            vals.append((math.inf, 0.0))
        elif i % 23 == 0 and i != 0:
            vals.append((-math.inf, 0.0))
        elif i % 29 == 0 and i != 0:
            vals.append((math.nan, 0.0))
        else:
            # large/small magnitudes alternating
            mag = 10.0 ** ((i % 8) - 4)  # 1e-4 .. 1e3
            vals.append((mag if (i % 2 == 0) else -mag, mag * 0.5))
    return _pack_complex(vals)


def _pattern_identity_block(n, block_n):
    # Emit block_n x block_n identity-like matrix flattened in column-major
    # (common BLAS expectation) followed by filler up to n elements.
    # Diagonal = 1+0i, off-diagonal small values.
    import math
    size = block_n * block_n
    vals = []
    for j in range(block_n):
        for i in range(block_n):
            if i == j:
                vals.append((1.0, 0.0))
            else:
                # small off-diagonal to keep conditioning reasonable
                vals.append((0.0, 0.0))
    # pad remainder with zeros if requested n is larger than size
    if n > size:
        vals.extend([(0.0, 0.0)] * (n - size))
    return _pack_complex(vals[:n])


