    # Emit a dim x dim Hermitian matrix in full storage (column-major flatten),
    # with real diagonal and conjugate symmetry; fill remainder with zeros.
    vals = []
    # build full matrix then flatten by columns
    mat = [[(0.0, 0.0) for _ in range(dim)] for _ in range(dim)]
    rng = random.Random(1337)
    for i in range(dim):
        # real diagonal
        mat[i][i] = (1.0 + 0.1 * i, 0.0)
        for j in range(i + 1, dim):
            a = (rng.uniform(-1, 1), rng.uniform(-1, 1))
            mat[i][j] = a
            # conjugate symmetry
            mat[j][i] = (a[0], -a[1])
    for j in range(dim):
        for i in range(dim):
            vals.append(mat[i][j])
    if dim * dim < n:
        vals.extend([(0.0, 0.0)] * (n - dim * dim))
    return _pack_complex(vals[:n])


def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    # Choose total complex elements to emit such that bytes <= MAX_BYTES
    # Each complex double = 16 bytes.
    max_elems = MAX_BYTES // 16

    # Decide segment plan: create several segments with different patterns and
    # sizes so that random slices taken by the fuzzer for vectors/matrices land
    # on diverse content. Keep segments small-to-medium.
    segments = []

    # Base sizes influenced by seed for variation
    def sz(lo, hi):
        return max(1, int(rng.randrange(lo, hi)))

    # Compose segments
    segments.append(_pattern_zeros(sz(8, 32)))
    segments.append(_pattern_ones(sz(8, 32)))
    segments.append(_pattern_i(sz(8, 32)))
    segments.append(_pattern_alternating(sz(32, 96)))
    segments.append(_pattern_small_integers(sz(32, 96)))
    segments.append(_pattern_sin_cos(sz(64, 160)))
    segments.append(_pattern_random_normal(sz(64, 160), rng))
    segments.append(_pattern_specials(sz(32, 96)))

    # Matrix-like blocks to serve for A/B/C in gemm/gemv/herk etc.
    dim_id = rng.choice([4, 5, 6, 7, 8])
    elements_needed = dim_id * dim_id
    segments.append(_pattern_identity_block(elements_needed, dim_id))

    dim_h = rng.choice([4, 5, 6])
    segments.append(_pattern_hermitian_block(dim_h * dim_h, dim_h))

    # Concatenate and trim to MAX_BYTES
    out = bytearray()
    for seg in segments:
        if len(out) + len(seg) > MAX_BYTES:
            # trim seg if needed
            need = MAX_BYTES - len(out)
            if need <= 0:
                break
            out += seg[:need]
            break
        out += seg

    # Ensure non-empty and aligned to 16 bytes is not necessary, but padding with zeros can help
    if len(out) == 0:
        out = _pattern_zeros(4)
    # Truncate to MAX_BYTES just in case
    return bytes(out[:MAX_BYTES])
